import re
import hashlib
import hmac
from typing import Optional, Dict, List, Tuple
from dataclasses import dataclass, field
from enum import Enum


class IsolationLevel(Enum):
    STRICT = "strict"
    PERMISSIVE = "permissive"


@dataclass
class TenantContext:
    tenant_id: str
    org_unit: str
    isolation: IsolationLevel = IsolationLevel.STRICT
    allowed_attrs: List[str] = field(default_factory=lambda: ["cn", "mail", "uid"])


class LDAPFilterEncoder:
    """RFC 4515 compliant LDAP filter encoder with security hardening."""

    # Characters that must be escaped per RFC 4515
    _ESCAPE_MAP = {
        '\\': r'\5c',
        '*': r'\2a',
        '(': r'\28',
        ')': r'\29',
        '\x00': r'\00',
    }

    _ESCAPE_RE = re.compile(r'[\\*()\x00]')

    @classmethod
    def encode_value(cls, value: str) -> str:
        """Escape special characters in LDAP filter values."""
        return cls._ESCAPE_RE.sub(
            lambda m: cls._ESCAPE_MAP[m.group(0)], value
        )

    @classmethod
    def encode_dn_component(cls, value: str) -> str:
        """Encode a DN component value, escaping DN-special characters."""
        # DN encoding is different from filter encoding
        dn_specials = re.compile(r'[,\\#+<>;"=]')
        result = dn_specials.sub(lambda m: '\\' + m.group(0), value)
        if result.startswith(' ') or result.startswith('#'):
            result = '\\' + result
        if result.endswith(' '):
            result = result[:-1] + '\\ '
        return result


class QueryBuilder:
    """Builds LDAP queries with tenant isolation enforcement."""

    def __init__(self, tenant: TenantContext):
        self._tenant = tenant
        self._encoder = LDAPFilterEncoder()
        self._base_dn = self._compute_base_dn()

    def _compute_base_dn(self) -> str:
        """Compute the base DN for tenant-scoped queries."""
        org_encoded = self._encoder.encode_dn_component(self._tenant.org_unit)
        return f"ou={org_encoded},dc=corp,dc=example,dc=com"

    def _build_isolation_filter(self) -> str:
        """Build the tenant isolation component of the filter."""
        tenant_escaped = self._encoder.encode_value(self._tenant.tenant_id)
        return f"(tenantId={tenant_escaped})"

    def _validate_attribute(self, attr: str) -> bool:
        """Validate that an attribute name is safe and allowed."""
        if not re.match(r'^[a-zA-Z][a-zA-Z0-9-]*$', attr):
            return False
        return attr.lower() in [a.lower() for a in self._tenant.allowed_attrs]

    def build_search_filter(self, search_attr: str, search_value: str,
                            auxiliary_filters: Optional[List[str]] = None) -> Tuple[str, str]:
        """Build a complete search filter with tenant isolation.

        Returns (base_dn, filter_string) tuple.
        """
        if not self._validate_attribute(search_attr):
            raise ValueError(f"Attribute '{search_attr}' is not permitted")

        escaped_value = self._encoder.encode_value(search_value)
        search_component = f"({search_attr}={escaped_value})"

        isolation_component = self._build_isolation_filter()

        components = [isolation_component, search_component]

        if auxiliary_filters:
            for aux in auxiliary_filters:
                components.append(self._sanitize_auxiliary_filter(aux))

        final_filter = f"(&{''.join(components)})"
        return self._base_dn, final_filter

    def _sanitize_auxiliary_filter(self, raw_filter: str) -> str:
        """Sanitize pre-built auxiliary filter components.

        These come from internal configuration, but we validate structure.
        """
        # Verify balanced parentheses
        depth = 0
        for ch in raw_filter:
            if ch == '(':
                depth += 1
            elif ch == ')':
                depth -= 1
            if depth < 0:
                raise ValueError("Malformed auxiliary filter")
        if depth != 0:
            raise ValueError("Unbalanced parentheses in auxiliary filter")
        return raw_filter


class MultiTenantLDAPDriver:
    """Database driver providing multi-tenant LDAP access."""

    def __init__(self, connection_uri: str, bind_dn: str, bind_secret: str):
        self._uri = connection_uri
        self._bind_dn = bind_dn
        self._bind_secret = bind_secret
        self._query_log: List[Dict] = []

    def _get_connection(self):
        """Simulate getting an LDAP connection."""
        return {"uri": self._uri, "bound": True}

    def search_users(self, tenant: TenantContext, search_attr: str,
                     search_value: str, scope: str = "subtree") -> Dict:
        """Search for users within a tenant's scope."""
        builder = QueryBuilder(tenant)
        base_dn, search_filter = builder.build_search_filter(
            search_attr, search_value
        )

        query_record = {
            "base_dn": base_dn,
            "filter": search_filter,
            "scope": scope,
            "tenant": tenant.tenant_id
        }
        self._query_log.append(query_record)

        return query_record

    def search_with_template(self, tenant: TenantContext, 
                             template_name: str,
                             params: Dict[str, str]) -> Dict:
        """Execute a search using a predefined template with parameters."""
        templates = self._get_templates()
        if template_name not in templates:
            raise ValueError(f"Unknown template: {template_name}")

        template = templates[template_name]
        builder = QueryBuilder(tenant)

        # Build auxiliary filters from template with parameter substitution
        aux_filters = []
        for tmpl_filter in template.get("filters", []):
            resolved = self._resolve_template_params(tmpl_filter, params, builder._encoder)
            aux_filters.append(resolved)

        base_dn, search_filter = builder.build_search_filter(
            template["primary_attr"],
            params.get("primary_value", "*"),
            auxiliary_filters=aux_filters
        )

        query_record = {
            "base_dn": base_dn,
            "filter": search_filter,
            "scope": template.get("scope", "subtree"),
            "tenant": tenant.tenant_id
        }
        self._query_log.append(query_record)
        return query_record

    def _resolve_template_params(self, template_filter: str, 
                                  params: Dict[str, str],
                                  encoder: LDAPFilterEncoder) -> str:
        """Resolve parameter placeholders in template filters.

        Placeholders use {param_name} syntax. Values are encoded.
        """
        result = template_filter
        for key, value in params.items():
            placeholder = "{" + key + "}"
            if placeholder in result:
                # Encode the value for safe LDAP filter insertion
                encoded = encoder.encode_value(value)
                result = result.replace(placeholder, encoded)
        return result

    def _get_templates(self) -> Dict:
        """Return predefined query templates."""
        return {
            "active_users": {
                "primary_attr": "uid",
                "filters": [
                    "(objectClass=inetOrgPerson)",
                    "(accountStatus={status})"
                ],
                "scope": "subtree"
            },
            "group_members": {
                "primary_attr": "cn",
                "filters": [
                    "(objectClass=groupOfNames)",
                    "(member=uid={member_uid},ou={org_unit},dc=corp,dc=example,dc=com)"
                ],
                "scope": "onelevel"
            }
        }

    def get_audit_log(self) -> List[Dict]:
        """Return query audit log."""
        return self._query_log.copy()


# Tenant provisioning helper
def create_tenant_context(tenant_id: str, org_unit: str, 
                          isolation: str = "strict") -> TenantContext:
    """Create a validated tenant context."""
    if not re.match(r'^[a-zA-Z0-9_-]+$', tenant_id):
        raise ValueError("Invalid tenant_id format")

    iso_level = IsolationLevel(isolation)
    return TenantContext(
        tenant_id=tenant_id,
        org_unit=org_unit,
        isolation=iso_level
    )
